WITH source_data AS
(
   SELECT
      BirthDate,
      CustomerKey,
      GeographyKey,
      CustomerAlternateKey,
      Title,
      FirstName,
      MiddleName,
      LastName,
      NameStyle,
      MaritalStatus,
      Suffix,
      Gender,
      EmailAddress,
      YearlyIncome,
      TotalChildren,
      NumberChildrenAtHome,
      EnglishEducation,
      SpanishEducation,
      FrenchEducation,
      EnglishOccupation,
      SpanishOccupation,
      FrenchOccupation,
      HouseOwnerFlag,
      NumberCarsOwned,
      AddressLine1,
      AddressLine2,
      Phone,
      DateFirstPurchase,
      CommuteDistance
   FROM
      {{ ref('stg_raw__ole_db_source') }}
)
SELECT
   BirthDate,
   CustomerKey,
   GeographyKey,
   CustomerAlternateKey,
   Title,
   FirstName,
   MiddleName,
   LastName,
   NameStyle,
   MaritalStatus,
   Suffix,
   Gender,
   EmailAddress,
   YearlyIncome,
   TotalChildren,
   NumberChildrenAtHome,
   EnglishEducation,
   SpanishEducation,
   FrenchEducation,
   EnglishOccupation,
   SpanishOccupation,
   FrenchOccupation,
   HouseOwnerFlag,
   NumberCarsOwned,
   AddressLine1,
   AddressLine2,
   Phone,
   DateFirstPurchase,
   CommuteDistance,
   BirthDate :: VARCHAR(50) AS BirthDateString
FROM
   source_data AS sd